import{c as e,Q as a,j as d,m as o}from"./chunks/framework.BXc4yaFE.js";const b=JSON.parse('{"title":"Claude Sonnet 5 完整指南","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/41-claude-sonnet-5.md","filePath":"research/best-practices/41-claude-sonnet-5.md","lastUpdated":1785909234000}'),r={name:"research/best-practices/41-claude-sonnet-5.md"};function l(n,t,i,s,c,u){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="claude-sonnet-5-完整指南" tabindex="-1">Claude Sonnet 5 完整指南 <a class="header-anchor" href="#claude-sonnet-5-完整指南" aria-label="Permalink to &quot;Claude Sonnet 5 完整指南&quot;">​</a></h1><blockquote><p>來源：<a href="https://www.anthropic.com/news/claude-sonnet-5" target="_blank" rel="noreferrer">Claude Sonnet 5</a>（2026-06-30） 來源：Claude Code changelog v2.1.197（2026-06-30） 整理日期：2026-07-06</p></blockquote><hr><h2 id="模型定位" tabindex="-1">模型定位 <a class="header-anchor" href="#模型定位" aria-label="Permalink to &quot;模型定位&quot;">​</a></h2><p><strong>Claude Sonnet 5</strong> 於 2026-06-30（Claude Code v2.1.197）發布，取代 Sonnet 4.6 成為 Claude Code <strong>預設模型</strong>。定位為「Agentic 能力大幅躍進」的平衡檔位——縮小與 Opus 4.8 的效能差距，同時維持遠低於 Opus/Fable 的成本。</p><hr><h2 id="技術規格" tabindex="-1">技術規格 <a class="header-anchor" href="#技術規格" aria-label="Permalink to &quot;技術規格&quot;">​</a></h2><table tabindex="0"><thead><tr><th>規格</th><th>值</th></tr></thead><tbody><tr><td>Model ID</td><td><code>claude-sonnet-5</code></td></tr><tr><td>Context window</td><td><strong>1M token</strong>（原生，changelog 公告文字）</td></tr><tr><td>輸入定價（促銷，至 2026-08-31）</td><td>$2 / MTok</td></tr><tr><td>輸出定價（促銷，至 2026-08-31）</td><td>$10 / MTok</td></tr><tr><td>輸入定價（促銷結束後，2026-09-01 起）</td><td>$3 / MTok</td></tr><tr><td>輸出定價（促銷結束後）</td><td>$15 / MTok</td></tr><tr><td>發布日期</td><td>2026-06-30</td></tr></tbody></table><p><strong>可用方案</strong>：Free / Pro 預設模型；Max / Team / Enterprise 可選用；Claude API、Claude Platform、Claude Code 均可存取。</p><hr><h2 id="能力與行為差異-對照-sonnet-4-6" tabindex="-1">能力與行為差異（對照 Sonnet 4.6） <a class="header-anchor" href="#能力與行為差異-對照-sonnet-4-6" aria-label="Permalink to &quot;能力與行為差異（對照 Sonnet 4.6）&quot;">​</a></h2><ul><li>Agentic 表現顯著提升：規劃、工具使用（browser/terminal）、自主連續執行的品質接近以往需要更大模型才能達到的水準</li><li>推理、工具呼叫、coding、知識工作任務全面優於 Sonnet 4.6</li><li>幻覺率與 sycophancy 降低</li><li>抵抗 prompt injection、拒絕惡意請求的能力提升</li><li><strong>安全</strong>：cyber safeguards 預設啟用；cybersecurity 能力明顯弱於 Opus 系列（設計上的限制，非 bug）</li></ul><hr><h2 id="claude-code-整合細節-v2-1-197-起" tabindex="-1">Claude Code 整合細節（v2.1.197 起） <a class="header-anchor" href="#claude-code-整合細節-v2-1-197-起" aria-label="Permalink to &quot;Claude Code 整合細節（v2.1.197 起）&quot;">​</a></h2><ul><li>取代 Sonnet 4.6 成為 CLI 預設模型（<code>/model</code> 不指定時的 fallback）</li><li>Subagent alias <code>sonnet</code> 解析至 <code>claude-sonnet-5</code></li><li>與同批（v2.1.198）「Subagent 預設背景執行」「Explore agent 繼承主 session 模型（上限 opus）」等變更同時生效，兩者常一併觸發舊 workflow 假設失效，升級後建議重新檢視 pin 設定與 subagent 檔位對照表</li></ul><hr><h2 id="模型選擇建議" tabindex="-1">模型選擇建議 <a class="header-anchor" href="#模型選擇建議" aria-label="Permalink to &quot;模型選擇建議&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情境</th><th>推薦模型</th></tr></thead><tbody><tr><td>一般日常工作馬（預設）</td><td><strong>Sonnet 5</strong></td></tr><tr><td>深推理 / 跨模組架構決策</td><td>Opus 4.8</td></tr><tr><td>稀缺頂配、需使用者顯式授權</td><td>Fable 5</td></tr><tr><td>預算敏感 batch 處理</td><td>Sonnet 5 / Haiku 4.5</td></tr><tr><td>Cybersecurity 主題</td><td>Opus 4.8（Sonnet 5 該能力刻意弱化）</td></tr></tbody></table><hr><h2 id="促銷定價注意事項" tabindex="-1">促銷定價注意事項 <a class="header-anchor" href="#促銷定價注意事項" aria-label="Permalink to &quot;促銷定價注意事項&quot;">​</a></h2><ul><li>2026-06-30 ~ 08-31：$2/$10（促銷）</li><li>2026-09-01 起：$3/$15（標準價，仍低於 Sonnet 4.6 同期水準）</li><li>促銷到期前若有大量批次任務，可提前排程於促銷窗口內完成以降低成本</li></ul><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><code>36-claude-fable-5.md</code> — Fable 5 / Mythos 5，稀缺頂配對照</li><li><code>42-w26-27-features.md</code> — 同批（v2.1.196–198）Claude in Chrome GA、Subagent 背景預設、Org default models 等變更</li><li><code>.claude/refs/model-profiles.md</code> — 本 workspace 檔位對應 SSoT（quality 檔位已 pin <code>claude-sonnet-5</code>）</li></ul>',24)])])}const p=e(r,[["render",l]]);export{b as __pageData,p as default};
